using SimplePZMapmaker.Core;
using SimplePZMapmaker.Core.Export;
namespace SimplePZMapmaker.Web.Services;

/// <summary>Adapts an immutable workspace lease; resource validation runs on the same revision as the writer.</summary>
internal sealed class WorkspaceExportSource(WorldSectionArchive.RevisionLease lease,WorldSectionArchive.Metadata metadata,GameAssetCatalog? assets,StaticModelCatalog? models):IStreamedWorldExportSource
{
 public WorldProject Metadata {get;}=new(){Version=metadata.Version,Id=metadata.Id,Name=metadata.Name,Buildings=metadata.Buildings,LinearFeatures=metadata.LinearFeatures,Fences=metadata.Fences,FenceStyles=metadata.FenceStyles,GateStyles=metadata.GateStyles,Decorations=metadata.Decorations,GeoReference=metadata.GeoReference,Elevation=metadata.Elevation};
 public IReadOnlyList<StreamedWorldSection> Sections {get;}=lease.PinnedManifest.Sections.Select(s=>new StreamedWorldSection(s.Id,s.Name,s.WorldX,s.WorldY,s.Width,s.Height)).ToArray();
 public object AuthoringIndex=>lease.PinnedManifest;
 public async Task<MapProject> ReadSectionAsync(string id,CancellationToken token){var p=await lease.ReadSectionAsync(id,token);var sharedTiles=metadata.FenceStyles.SelectMany(s=>new[]{s.W,s.N,s.NW,s.Post,s.WAlt,s.NAlt}.OfType<string>()).Concat(metadata.GateStyles.SelectMany(s=>s.ClosedW.Concat(s.ClosedN).Concat(s.OpenW).Concat(s.OpenN))).ToHashSet(StringComparer.Ordinal);var fenceOwners=p.AssetSources.Where(pair=>sharedTiles.Contains(pair.Key)).ToArray();if(assets is not null)AssetRules.Project(p,assets);foreach(var pair in fenceOwners)p.AssetSources.TryAdd(pair.Key,pair.Value);models?.Validate(p);return p;}
 public async Task<MapProject> ProjectSectionAsync(string id,MapProject authored,CancellationToken token){var shared=WorldSectionProjection.Context(metadata,authored);foreach(var building in shared.Buildings){if(assets is not null)AssetRules.Building(building,assets);if(models is not null)ModelRules.Building(building,models);}if(assets?.Ready==true)AssetRules.StampDeckArtwork(shared.LinearFeatures,assets);var p=await lease.ProjectSectionAsync(id,authored,metadata,token);if(assets?.Ready==true){foreach(var tile in (p.SharedInfrastructure?.Tiles.Where(t=>!t.Artwork).Select(t=>t.Id)??[]).Concat(p.Decorations.Where(d=>d.Id.StartsWith("world-",StringComparison.Ordinal)).SelectMany(d=>d.Parts.Select(part=>part.Tile))).Distinct())if(assets.Get(tile).Source!="game")throw new ArgumentException("Shared infrastructure requires the original game resource provider: "+tile);ValidateDeckResources(p,assets);ValidateFenceResources(p,assets);}return p;}
 public static void ValidateDeckResources(MapProject p,GameAssetCatalog assets){var ids=(p.SharedInfrastructure?.Tiles.Where(t=>t.Artwork).Select(t=>t.Id)??[]).Distinct().ToArray();foreach(var id in ids){AssetRules.CheckDeckArtwork(assets,id);var provider=assets.Get(id).ModId??"game";if(p.AssetSources.TryGetValue(id,out var saved)&&saved!=provider)throw new ArgumentException("Shared deck artwork has a different resource provider: "+id);p.AssetSources[id]=provider;}p.RequiredMods=p.RequiredMods.Concat(assets.ResolveRequirements(ids).Select(m=>m.ModId)).Distinct(StringComparer.Ordinal).ToList();}
 /// <summary>Resolve actual fence pieces through the active catalog and enforce every available saved owner.</summary>
 public static void ValidateFenceResources(MapProject p,GameAssetCatalog assets,IReadOnlyDictionary<string,string>? savedSources=null){
  if(!assets.Ready||p.Fences.Count==0)return;var ids=FenceLines.Compose(p.Fences,p.FenceStyles,p.GateStyles,p.Width,p.Height,blocked:FenceLines.Blocker(p)).Pieces.Select(piece=>piece.Tile).Distinct(StringComparer.Ordinal).ToArray();var sources=new Dictionary<string,string>(p.AssetSources,StringComparer.Ordinal);foreach(var id in ids){var provider=assets.Get(id).ModId??"game";var original=savedSources?.GetValueOrDefault(id)??sources.GetValueOrDefault(id);if(original is not null&&original!=provider)throw new ArgumentException($"Tile {id} has a different source: expected {original}, active {provider}. Enable the original mod.");sources[id]=provider;}p.AssetSources=sources;p.RequiredMods=p.RequiredMods.Concat(assets.ResolveRequirements(ids).Select(m=>m.ModId)).Distinct(StringComparer.Ordinal).ToList();ResourceDependencies.Validate(p.RequiredMods,p.AssetSources);
 }
 public Task CopySectionSourceAsync(string id,Stream target,CancellationToken token)=>lease.CopySectionSourceAsync(id,target,token);
 public Task CopyMetadataSourceAsync(Stream target,CancellationToken token)=>lease.CopyMetadataSourceAsync(target,token);
}
